import os
import sys
import unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
import json


class Tests(unittest.TestCase):
    def test_every_item_has_sku_and_qty(self):
        feed = json.load(open(os.path.join(ROOT, "partner", "feed-sample.json")))
        for item in feed["items"]:
            self.assertIn("sku", item)
            self.assertIn("qty", item)


if __name__ == "__main__":
    unittest.main()
